      elem(ID.Info, concat([
        elem(ID.TimecodeScale, uint(1_000_000)),
        elem(ID.MuxingApp, text(APP)),
        elem(ID.WritingApp, text(APP)),
        elem(ID.Duration, f64(this.durationMs)),
      ])),
      elem(ID.Tracks, concat([this.#videoTrack(), ...(this.audio ? [this.#audioTrack()] : [])])),
