  }

  #track(num, type, codecId, extra) {
    return elem(ID.TrackEntry, concat([
      elem(ID.TrackNumber, uint(num)),
      elem(ID.TrackUID, uint(num)),
      elem(ID.FlagLacing, uint(0)),
      elem(ID.CodecID, text(codecId)),
      elem(ID.TrackType, uint(type)),
      ...extra,
